  paid:     { s: 'rgba(255,255,255,0.40)', w: 1.25, dash: '1.5 3.5', fill: 'rgba(255,255,255,0.02)',  chair: 'rgba(255,255,255,0.20)', t: 'rgba(255,255,255,0.40)' },
