  out:      { s: 'rgba(255,255,255,0.12)', w: 1,    dash: '2 4',     fill: 'rgba(255,255,255,0.00)',  chair: 'rgba(255,255,255,0.06)', t: 'rgba(255,255,255,0.18)' },
