const _catPr = (n) => _catL(`${n} produit${n > 1 ? 's' : ''}`, `${n} product${n === 1 ? '' : 's'}`, n === 1 ? 'منتج واحد' : n === 2 ? 'منتجان' : `${n} ${n > 10 ? 'منتجًا' : 'منتجات'}`);
